import kwh from './kwh'

const fanPriceRub = {
	kwhv: 7140,
	kwhv24: 14500,
} as const

type FanConvector = {
	model_id: 'kwhv' | 'kwhv24'
	slug: string
	dt70: number
	width: number
	height: number
	length: number
	fans_qnty: number
	related_items: string
	addon_stainless_body: string
	basiс_grille_price: number
	anod_color_grille_price: number
	some_ral_grill: number
	premium_grille_price: number
	wood_grill_price: number
	grill_empty: number
}

const sizeKey = ({ width, height, length }: { width: number; height: number; length: number }) =>
	`${width}-${height}-${length}`

const basePriceBySize = new Map(kwh.map(convector => [sizeKey(convector), convector.price]))
const grilleKey = ({ width, length }: { width: number; length: number }) => `${width}-${length}`
const grillePriceFields = [
	'basiс_grille_price',
	'anod_color_grille_price',
	'some_ral_grill',
	'premium_grille_price',
	'wood_grill_price',
] as const
const grilleBySize = new Map<string, (typeof kwh)[number]>()

for (const convector of kwh) {
	const key = grilleKey(convector)
	const existing = grilleBySize.get(key)
	if (existing && grillePriceFields.some(field => existing[field] !== convector[field]))
		throw new Error(`Цена решётки KWH зависит от глубины: ${key}`)
	grilleBySize.set(key, convector)
}

