const v220BySize = new Map<string, FanConvector>()
const v24BySize = new Map<string, FanConvector>()

for (const variant of variants) {
	const bySize = variant.model_id === 'kwhv' ? v220BySize : v24BySize
	const key = sizeKey(variant)
	if (bySize.has(key)) throw new Error(`Повтор конвектора ${variant.model_id} ${key}`)
	bySize.set(key, variant)
	if (!basePriceBySize.has(key)) throw new Error(`Нет базовой цены KWH для ${variant.model_id} ${key}`)
	const grille = grilleBySize.get(grilleKey(variant))
	if (!grille || grillePriceFields.some(field => grille[field] !== variant[field]))
		throw new Error(`Цена решётки ${variant.model_id} отличается от KWH: ${key}`)
}

if (v220BySize.size !== v24BySize.size) throw new Error('Количество моделей KWHV 220 В и 24 В различается')

for (const [key, v220] of v220BySize) {
	const v24 = v24BySize.get(key)
	if (!v24 || v220.fans_qnty !== v24.fans_qnty)
		throw new Error(`Не совпадают аналоги KWHV 220 В и 24 В: ${key}`)
	if (
		v220.basiс_grille_price !== v24.basiс_grille_price ||
		v220.anod_color_grille_price !== v24.anod_color_grille_price ||
		v220.some_ral_grill !== v24.some_ral_grill ||
		v220.premium_grille_price !== v24.premium_grille_price ||
		v220.wood_grill_price !== v24.wood_grill_price
	) throw new Error(`Не совпадают цены решёток KWHV 220 В и 24 В: ${key}`)
}

export default variants.map(variant => {
	const key = sizeKey(variant)
	const basePrice = basePriceBySize.get(key)
	if (basePrice === undefined) throw new Error(`Нет базовой цены KWH для ${variant.model_id} ${key}`)
	return {
		...variant,
		price: basePrice + fanPriceRub[variant.model_id] * variant.fans_qnty,
	}
})
